jQuery(document).ready(function($) {
    // Toggle service description on header click
    $('.service-header').click(function() {
        $(this).next('.service-description').slideToggle();
    });

    // Hide the page loader on page load
    $("#page-loader").fadeOut(500);

    // Show the loader when a link is clicked (except for certain cases)
    $("a").on("click", function(e) {
        if ($(this).attr("target") !== "_blank" && $(this).attr("href") !== "#" && $(this).attr("href").indexOf("mailto:") === -1) {
            $("#page-loader").fadeIn(300);
        }
    });

    // Fix the issue for the back/forward navigation
    $(window).on('pageshow pagehide', function(event) {
        if (event.type === 'pageshow') {
            // Ensure loader is hidden when returning to the page
            $("#page-loader").fadeOut(500);
        } else if (event.type === 'pagehide') {
            // Show loader again when the page is hidden (browser back/forward)
            $("#page-loader").fadeIn(300);
        }
    });
});
